from lib import *
N=11
TITLE='חסינות חברי כנסת'
SUM=[
h3('11.1 מהי חסינות ולמה היא קיימת'),
p('חסינות היא הגנה מיוחדת שניתנת לחברי כנסת ומונעת נקיטת הליכים משפטיים נגדם בנסיבות מסוימות. תכליתה אינה להעניק זכות-יתר אישית לנבחר, אלא <b>להגן על עצמאות הרשות המחוקקת</b>: חבר כנסת צריך להיות מסוגל למלא את תפקידו, לבקר את הממשלה ולהצביע, בלי חשש מרדיפה משפטית או שלטונית. מכאן שהחסינות נמדדת לפי שיקול של תפקוד הפרלמנט, ולא לפי רצונו של חבר כנסת כזה או אחר. ההסדר מעוגן בחוק יסוד: הכנסת ובחוק חסינות חברי הכנסת, זכויותיהם וחובותיהם, התשי"א-1951.'),
h3('11.2 שני סוגי חסינות'),
tbl(['','חסינות מהותית (עניינית)','חסינות דיונית (פרוצדורלית)'],[
['מה מוגן','פעולות ואמירות במילוי התפקיד','היעדר הליך פלילי בענייני חבר הכנסת'],
['טיב ההגנה','מוחלטת; אינה ניתנת להסרה','יחסית; ניתנת להסרה, וצומצמה מאוד'],
['היקף','אחריות פלילית ואזרחית','הליכים פליליים בלבד'],
['מקור','ס׳ 1 לחוק החסינות','פרקים בחוק החסינות (כולל תיקון 29)']]),
h3('11.3 החסינות המהותית'),
p('ס׳ 1 לחוק החסינות קובע שחבר כנסת לא יישא באחריות פלילית או אזרחית בשל הצבעה, הבעת דעה או פעולה, בין בכנסת ובין מחוץ לה, <b>במילוי תפקידו או למען מילוי תפקידו</b>. זו הגנה חזקה על חופש הפעולה הפרלמנטרי. אי אפשר "לחסל" אותה בהחלטת הכנסת. לכן השאלה המרכזית היא: מתי פעולה נחשבת "במילוי התפקיד"?'),
box('def','מבחני הזיקה לתפקיד (לפי הפסיקה)','נקבעו מבחני עזר לקביעת הזיקה. <b>מבחן הסיכון הטבעי</b> - האם הפעולה היא חלק מהסיכונים הטבעיים הכרוכים בתפקיד חבר כנסת. <b>מבחן הזיקה</b> - עד כמה הפעולה קשורה עניינית למילוי התפקיד. פעולה פלילית מובהקת, כמו לקיחת שוחד או זיוף, חורגת מכל סיכון טבעי ואינה מוגנת.'),
box('case','בשארה - גבולות הפעולה הפוליטית','נדונה השאלה אם אמירות פוליטיות מסוימות חוסות תחת החסינות המהותית. נקבע שגם לחסינות המהותית יש גבולות: אמירה שיש בה תמיכה במאבק מזוין נגד המדינה או בארגון טרור חורגת מגדר מילוי תפקיד לגיטימי ואינה מוגנת. ההלכה: החסינות מגינה על שיח פוליטי לגיטימי, לא על כל אמירה. הכרטיס מציג את העיקרון הכללי ואינו מתאר את תוצאת ההליכים בפרשה.'),
h3('11.4 החסינות הדיונית ותיקון 29'),
p('בעבר נהנו חברי כנסת מחסינות דיונית רחבה: כל העמדה לדין פלילי חייבה אישור הכנסת, ובפועל ההגנה הייתה כמעט אוטומטית. <b>תיקון 29</b> (2005) שינה את נקודת המוצא. כיום, ככלל, ניתן להעמיד חבר כנסת לדין בעבירה פלילית "רגילה" על ידי היועץ המשפטי לממשלה. חבר הכנסת רשאי לבקש מהכנסת להעניק לו חסינות מפני ההליך. הכנסת רשאית להעניק חסינות רק בעילות מצומצמות, למשל כשהמעשה נעשה במילוי התפקיד או כשיש חשש להעמדה לדין שנובעת משיקולים זרים או מהפליה. המגמה היא צמצום פערי המעמד בין חבר כנסת לאזרח בעבירות פליליות רגילות.'),
box('law','נקודות לתיקון 29','נקודת המוצא: אין חסינות דיונית אוטומטית. הבקשה לחסינות מוגשת לכנסת. ההכרעה נעשית בדרך כלל ברוב חברי הכנסת בנוכחות הצדדים. העילות מצומצמות ואינן נוגעות להגנה על מעמד בלבד.'),
h3('11.5 המתח בין חסינות לשוויון בפני החוק'),
p('מבקריה של החסינות טוענים שהיא פוגעת בשלטון החוק ובשוויון בפני החוק, שכן נבחרי ציבור אינם צריכים לקבל הגנה שמעבר לאזרחים. התומכים טוענים שהיא הכרחית לתפקוד הפרלמנט, ושבלעדיה אפשר יהיה להשתמש בהליכים פליליים כנשק פוליטי נגד נבחרים. הפתרון בישראל מאזן ביניהם: חסינות מהותית רחבה, דיונית מצומצמת. הרעיון הוא שהמעשה שבתפקיד מוגן, וההליך הפלילי נגד העבירה הפרטית אינו מוגן.'),
box('warn','מלכודות נפוצות',['לבלבל בין מהותית (על מילוי תפקיד) לדיונית (על ההליך).','לטעון שהחסינות המהותית ניתנת להסרה - אינה ניתנת.','לטעון שחבר כנסת חסין מפני כל הליך פלילי - אחרי תיקון 29 הוא מוגן רק בחסינות מצומצמת.','להניח שכל אמירה פוליטית מוגנת - יש גבולות.']),
h3('11.6 שלד לפתרון שאלה'),
ol('מהי הפעולה? אמירה, הצבעה או מעשה?','האם נעשתה במילוי התפקיד או למענו? החל מבחני הסיכון הטבעי והזיקה.','אם כן - חסינות מהותית: אין אחריות פלילית או אזרחית.','אם לא - חסינות דיונית: ניתן להעמיד לדין, וחבר הכנסת יכול לבקש חסינות בעילות מצומצמות.','בדוק אם המעשה פלילי מובהק, שחורג מהתפקיד.'),
box('ex','תרגיל פתור','חבר כנסת נאם בכנסת ובתקשורת נגד פקיד, ונתבע בלשון הרע. מנגד, אותו חבר כנסת נחשד בקבלת שוחד. <b>פתרון:</b> הנאום שבתפקיד מוגן בחסינות מהותית. השוחד אינו במילוי התפקיד, ולכן אין חסינות מהותית, ויש לבדוק רק אם הכנסת תעניק חסינות דיונית בעילות המצומצמות.'),
box('key','סיכום הפרק',['חסינות = הגנה על עצמאות הכנסת, לא זכות אישית.','מהותית: מוחלטת, על מילוי תפקיד (ס׳ 1).','דיונית: יחסית; תיקון 29 צמצם.','מבחני סיכון טבעי וזיקה; עבירה פלילית מובהקת אינה מוגנת.'])
]
CASES=[
('חוק חסינות חברי הכנסת, זכויותיהם וחובותיהם, התשי"א-1951, ס׳ 1','הסדר חקיקתי של חסינות מהותית.','חבר כנסת לא יישא באחריות פלילית או אזרחית בשל הצבעה, הבעת דעה או פעולה במילוי תפקידו או למענו. למבחן: החסינות המהותית מוחלטת.'),
('תיקון 29 לחוק החסינות (2005)','צמצום החסינות הדיונית.','נקודת המוצא: ניתן להעמיד חבר כנסת לדין פלילי; חסינות ניתנת רק בעילות מצומצמות. למבחן: שינוי נקודת המוצא.'),
('ch11.py','מבחני הזיקה לתפקיד','שאלת הזיקה בין פעולת חבר כנסת למילוי תפקידו.','נקבעו מבחני עזר: סיכון טבעי וזיקה לתפקיד. עבירה פלילית מובהקת אינה מוגנת. למבחן: הלכת הזיקה.'),
('פרשת בשארה','אמירות פוליטיות שנטען שהן חוסות תחת חסינות מהותית.','לחסינות המהותית יש גבולות; תמיכה במאבק מזוין או בטרור חורגת ממילוי תפקיד לגיטימי. למבחן: גבולות החסינות. הכרטיס מציג עיקרון כללי ולא את פרטי ההליכים.')
]
QS=[
Q('מהי תכלית החסינות של חברי כנסת?','הגנה על עצמאות הרשות המחוקקת',['העשרת חברי הכנסת','הענקת פטור ממס','מניעת ביקורת עליהם'],'חסינות חברי הכנסת נועדה להבטיח את עצמאות הכנסת ואת תפקודה התקין, ולא להעניק זכות אישית לחבר הכנסת. מניעת ביקורת, פטור ממס והעשרה אינן תכלית לגיטימית וסותרות את שוויון הכול בפני החוק.'),
Q('מהם שני סוגי החסינות?','מהותית ודיונית',['פלילית ואזרחית','מוחלטת ומוסרית','ארצית ומקומית'],'החלוקה המקובלת בחוק היא חסינות מהותית, על פעולות במילוי התפקיד, וחסינות דיונית, מפני העמדה לדין. אחריות פלילית ואזרחית הן סוגי אחריות ולא סוגי חסינות, ושאר האפשרויות אינן חלוקה מוכרת.'),
Q('מהי החסינות המהותית?','הגנה על פעולות ואמירות במילוי התפקיד',['הגנה מפני כל הליך פלילי','הגנה מפני מיסים','הגנה מפני ביקורת'],'החסינות המהותית מגינה על פעולות ואמירות של חבר הכנסת במילוי תפקידו, ופוטרת מאחריות פלילית ואזרחית. הגנה מפני כל הליך פלילי היא רחבה מדי וקרובה לחסינות הדיונית, ולא למהותית.'),
Q('האם ניתן להסיר את החסינות המהותית?','לא, היא מוחלטת',['כן, ברוב רגיל','כן, בהחלטת הממשלה','כן, בהחלטת בג"ץ'],'החסינות המהותית היא מוחלטת: היא נובעת מהחוק ואינה תלויה בבקשה או בהחלטה של הכנסת. לכן לא בג"ץ, לא רוב רגיל בכנסת ולא הממשלה יכולים להסירה, בשונה מחסינות דיונית שהכנסת מכריעה בה.'),
Q('מהי החסינות הדיונית?','הגנה מפני העמדה לדין פלילי, הניתנת בהחלטת הכנסת',['הגנה על נאומים','הגנה על הצבעות','הגנה על קניין'],'החסינות הדיונית נוגעת להליך: היא מגינה מפני העמדה לדין פלילי, ונקבעת בהחלטת הכנסת בעילות מוגדרות. נאומים והצבעות מוגנים בחסינות המהותית, ולכן אינם הגדרת הדיונית.'),
Q('מה שינה תיקון 29?','צמצם את החסינות הדיונית',['הרחיב את החסינות','ביטל את החסינות המהותית','העביר את הסמכות לבג"ץ'],'תיקון 29 לחוק החסינות (2005) צמצם את החסינות הדיונית: מעמד של חבר כנסת אינו עוד הגנה אוטומטית מפני הליך פלילי, ובכך חיזק את שוויון הכול בפני החוק. הרחבה או ביטול המהותית הפוכים לתיקון.'),
Q('לפי תיקון 29, כיום ניתן להעמיד חבר כנסת לדין:','ככלל כן, על ידי היועץ המשפטי לממשלה',['רק באישור הכנסת','לעולם לא','רק אחרי פרישה'],'אחרי תיקון 29 נקודת המוצא היא שניתן להעמיד חבר כנסת לדין, וחסינות דיונית אינה אוטומטית אלא תלויה בבקשתו ובהחלטת הכנסת. לכן הטענה שלעולם לא או שרק באישור מוקדם היא תיאור של המצב הקודם.'),
Q('מי רשאי להעניק חסינות דיונית לחבר כנסת?','הכנסת, בעילות מצומצמות',['הממשלה','בג"ץ','נשיא המדינה'],'חסינות דיונית ניתנת על ידי הכנסת עצמה, בעילות מצומצמות שנקבעו בחוק, ואינה נתונה לרשות אחרת. הממשלה, בג"ץ ונשיא המדינה אינם מוסמכים להעניק אותה, ולכן הם אינם התשובה הנכונה.'),
Q('איזה מבחן קובע זיקה לתפקיד?','סיכון טבעי וזיקה',['מבחן האמצעי הפחות פוגע','מבחן הוודאות הקרובה','מבחן ההתאמה'],'לפי הפסיקה, היקף החסינות המהותית נבחן במבחני זיקה לתפקיד, ובהם מבחן הסיכון הטבעי הכרוך בתפקיד. מבחן ההתאמה והאמצעי הפחות פוגע שייכים לפסקת ההגבלה, והוודאות הקרובה לחופש הביטוי, לא לחסינות.'),
Q('האם לקיחת שוחד מוגנת בחסינות מהותית?','לא, אינה במילוי התפקיד',['כן, תמיד','כן, אם נעשתה בכנסת','כן, אם אושרה בכנסת'],'שוחד הוא עבירה פלילית מובהקת, שאינה חלק מתפקיד חבר הכנסת ואינה נעשית "במילוי תפקידו". לכן החסינות המהותית אינה חלה עליה, גם אם בוצעה בתוך בניין הכנסת.'),
Q('האם נאום בכנסת מוגן?','כן, בחסינות מהותית',['לא','רק אם אושר','רק מחוץ לכנסת'],'נאום בכנסת במסגרת מילוי התפקיד מוגן בחסינות מהותית, ואין תנאי של אישור מוקדם. הטענה שהנאום אינו מוגן שגויה, והחסינות אינה מוגבלת לנאומים שנישאו מחוץ לכנסת.'),
Q('מה הביקורת על החסינות?','פגיעה בשוויון בפני החוק',['הגדלת כוח הכנסת','פגיעה בעיתונות','פגיעה בצבא'],'הביקורת המרכזית על החסינות היא שהיא פוגעת בשוויון בפני החוק, כי היא מעניקה מעמד מועדף לחברי כנסת בהליך הפלילי. פגיעה בצבא או בעיתונות אינה הטענה המקובלת נגד החסינות.'),
Q('מה הטיעון בעד חסינות?','מניעת שימוש בהליכים פליליים כנשק פוליטי',['מתן פטור לעבירות','הגדלת שכר','ביטול ביקורת'],'התומכים בחסינות טוענים שהיא מונעת שימוש בהליכים פליליים כנשק פוליטי נגד נבחרי ציבור, ובכך שומרת על חופש הפעולה של הפרלמנט. הגדלת שכר או פטור מעבירות אינם טיעון לגיטימי להצדקתה.'),
Q('מה נקבע בפסיקה לגבי גבולות החסינות המהותית?','יש לה גבולות: פעולה שחורגת ממילוי התפקיד אינה מוגנת',['כל אמירה מוגנת','אין חסינות כלל','החסינות מוחלטת בכל עניין'],'לחסינות המהותית יש גבולות: פעולה החורגת ממילוי תפקיד חבר הכנסת, כמו עבירה פלילית מובהקת, אינה מוגנת. הטענה שהחסינות מוחלטת בכל עניין או שכל אמירה מוגנת שגויה, וקביעה שאין חסינות כלל סותרת את החוק.'),
Q('החסינות המהותית חלה על:','אחריות פלילית ואזרחית',['אחריות פלילית בלבד','אחריות אזרחית בלבד','אחריות מנהלית'],'ס׳ 1 לחוק החסינות פוטר חבר כנסת מאחריות פלילית ומאחריות אזרחית על פעולותיו במילוי תפקידו. לכן הגבלה לאחריות אזרחית בלבד, לפלילית בלבד או למנהלית אינה נכונה.'),
Q('איזה חוק מסדיר חסינות חברי כנסת?','חוק חסינות חברי הכנסת, זכויותיהם וחובותיהם',['חוק העונשין','חוק השבות','חוק הגנת הפרטיות'],'ההסדר נמצא בחוק חסינות חברי הכנסת, זכויותיהם וחובותיהם. חוק השבות עוסק בעלייה, חוק העונשין בעבירות, וחוק הגנת הפרטיות בפרטיות מידע, ולכן אף אחד מהם אינו מסדיר חסינות.'),
Q('מהי "הזיקה" במבחן?','קשר ענייני בין הפעולה לתפקיד',['קשר משפחתי','קשר עסקי','קשר פוליטי'],'הזיקה היא קשר ענייני בין הפעולה לבין תפקידו של חבר הכנסת, ובלי קשר כזה אין חסינות מהותית. קשר משפחתי, פוליטי או עסקי אינו הופך פעולה למילוי תפקיד.'),
Q('בנקודת המוצא של תיקון 29, חסינות דיונית:','אינה אוטומטית',['אוטומטית','מוחלטת','ניתנת לנשיא'],'לאחר תיקון 29 חסינות דיונית אינה אוטומטית אלא תלויה בהחלטת הכנסת, ולכן הטענה שהיא מוחלטת או אוטומטית שגויה. נשיא המדינה אינו מעניק אותה, ותפקיד זה נתון לכנסת.'),
Q('איזה משפט נכון?','חסינות היא הגנה על הכנסת ולא זכות אישית',['חסינות היא זכות אישית','חסינות מעניקה פטור מוחלט','חסינות מבטלת שוויון'],'החסינות נועדה להגן על תפקוד הכנסת ולא להעניק זכות אישית לחבר הכנסת, ולכן נקבעו לה גבולות. הטענות שהיא פטור מוחלט, זכות אישית או שמבטלת שוויון מתעלמות מהמגבלות שבחוק.'),
Q('מה נבחן בשאלת חסינות ראשית?','האם הפעולה במילוי התפקיד',['האם המפלגה גדולה','האם חבר הכנסת ותיק','האם יש תקציב'],'השאלה הראשונה בבחינת חסינות היא האם הפעולה נעשתה במילוי התפקיד, כי רק פעולה כזו נהנית מחסינות מהותית. תקציב, ותק של חבר הכנסת או גודל המפלגה אינם רלוונטיים לשאלה.'),
]
